export function xtime(value) {
  return (((value << 1) & 0xff) ^ ((value & 0x80) !== 0 ? 0x1b : 0x00)) & 0xff;
}

function multiply(a, b) {
  let left = a;
  let right = b;
  let product = 0;

  while (right > 0) {
    if ((right & 1) !== 0) {
      product ^= left;
    }
    left = xtime(left);
    right >>>= 1;
  }

  return product & 0xff;
}

function power(base, exponent) {
  let value = base;
  let powerValue = exponent;
  let result = 1;

  while (powerValue > 0) {
    if ((powerValue & 1) !== 0) {
      result = multiply(result, value);
    }
    value = multiply(value, value);
    powerValue >>>= 1;
  }

  return result;
}

function rotateLeft8(value, shift) {
  return ((value << shift) | (value >>> (8 - shift))) & 0xff;
}

function createSBox() {
  const table = new Uint8Array(256);

  for (let value = 0; value < 256; value += 1) {
    const inverse = value === 0 ? 0 : power(value, 254);
    table[value] =
      inverse ^
      rotateLeft8(inverse, 1) ^
      rotateLeft8(inverse, 2) ^
      rotateLeft8(inverse, 3) ^
      rotateLeft8(inverse, 4) ^
      0x63;
  }

  return table;
}

function createRcon() {
  const table = new Uint32Array(15);
  let value = 1;

  for (let index = 1; index < table.length; index += 1) {
    table[index] = (value << 24) >>> 0;
    value = xtime(value);
  }

  return table;
}

export const S_BOX = createSBox();
export const RCON = createRcon();

