export function formatPythonBytesLiteral(bytesLike) {
  const bytes = bytesLike instanceof Uint8Array ? bytesLike : Uint8Array.from(bytesLike);

  let hasSingleQuote = false;
  let hasDoubleQuote = false;
  for (const byte of bytes) {
    if (byte === 0x27) {
      hasSingleQuote = true;
    } else if (byte === 0x22) {
      hasDoubleQuote = true;
    }
  }

  const quote = hasSingleQuote && !hasDoubleQuote ? '"' : "'";
  const quoteByte = quote.charCodeAt(0);
  let result = `b${quote}`;

  for (const byte of bytes) {
    if (byte === 0x09) {
      result += '\\t';
    } else if (byte === 0x0a) {
      result += '\\n';
    } else if (byte === 0x0d) {
      result += '\\r';
    } else if (byte === 0x5c) {
      result += '\\\\';
    } else if (byte === quoteByte) {
      result += `\\${quote}`;
    } else if (byte >= 0x20 && byte <= 0x7e) {
      result += String.fromCharCode(byte);
    } else {
      result += `\\x${byte.toString(16).padStart(2, '0')}`;
    }
  }

  return `${result}${quote}`;
}

